#include <memory>
#include <string>

class Robot {
public:
    explicit Robot(const std::string& name) : name_(name) {
        std::cout << name_ << " powered on\n";
    }
    ~Robot() {
        std::cout << name_ << " shut down\n";
    }
    void move(int steps) {
        position_ += steps;
    }
    std::string name() const { return name_; }
    int position() const { return position_; }

