#include <iostream>
#include <memory>
#include <string>
#include <utility>

class Task {
public:
    explicit Task(const std::string& name) : name_(name) {}
    ~Task() {
        std::cout << "destroyed " << name_ << '\n';
    }
    std::string name() const { return name_; }

private:
    std::string name_;
};

std::unique_ptr<Task> makeTask(const std::string& name) {
    return std::make_unique<Task>(name);
}

void finish(std::unique_ptr<Task> t) {
    std::cout << "finishing " << t->name() << '\n';
}

int main() {
    auto inbox = makeTask("report");
    std::unique_ptr<Task> doing = std::move(inbox);
    std::cout << "inbox is " << (inbox ? "full" : "empty") << '\n';
    if (doing != nullptr) {
        std::cout << "doing holds " << doing->name() << '\n';
    }
    finish(std::move(doing));
    std::cout << "after finish\n";
    std::cout << "doing is " << (doing ? "full" : "empty") << '\n';
    return 0;
}

