#include <iostream>
#include <memory>
#include <utility>

class Order {
public:
    explicit Order(int id) : id_(id) {}
    ~Order() {
        std::cout << "order " << id_ << " deleted\n";
    }
    int id() const { return id_; }

private:
    int id_;
};

std::unique_ptr<Order> makeOrder(int id) {
    return std::make_unique<Order>(id);
}

int main() {
    auto pending = makeOrder(42);
    std::unique_ptr<Order> shipped = std::move(pending);
    std::cout << "pending is " << (pending ? "full" : "empty") << '\n';
    if (shipped != nullptr) {
        std::cout << "shipped holds order " << shipped->id() << '\n';
    }
    shipped.reset();
    std::cout << "shipped is " << (shipped ? "full" : "empty") << '\n';
    std::cout << "done\n";
    return 0;
}

