#include <iostream>
#include <memory>
#include <string>

class Document {
public:
    explicit Document(const std::string& title) : title_(title) {}
    ~Document() {
        std::cout << title_ << " deleted\n";
    }
    std::string title() const { return title_; }

private:
    std::string title_;
};

int main() {
    std::shared_ptr<Document> archive;
    {
        auto doc = std::make_shared<Document>("notes");
        std::cout << "owners " << doc.use_count() << '\n';
        {
            auto editor = doc;
            std::cout << "owners " << doc.use_count() << '\n';
            std::cout << "editing " << editor->title() << '\n';
        }
        std::cout << "owners " << doc.use_count() << '\n';
        archive = doc;
        std::cout << "owners " << doc.use_count() << '\n';
    }
    std::cout << "owners " << archive.use_count() << '\n';
    archive.reset();
    std::cout << "owners " << archive.use_count() << '\n';
    std::cout << "end of main\n";
    return 0;
}

