#include <iostream>
#include <memory>
#include <string>

class Playlist {
public:
    explicit Playlist(const std::string& name) : name_(name) {}
    ~Playlist() {
        std::cout << "playlist deleted\n";
    }
    std::string name() const { return name_; }

private:
    std::string name_;
};

int main() {
    {
        auto playlist = std::make_shared<Playlist>("Road Trip");
        std::cout << "owners " << playlist.use_count() << '\n';
        {
            auto alice = playlist;
            std::cout << "owners " << playlist.use_count() << '\n';
            {
                auto bob = playlist;
                std::cout << "owners " << playlist.use_count() << '\n';
                std::cout << "bob is playing " << bob->name() << '\n';
            }
            std::cout << "owners " << playlist.use_count() << '\n';
        }
        std::cout << "owners " << playlist.use_count() << '\n';
        std::cout << "leaving block\n";
    }
    std::cout << "end of main\n";
    return 0;
}
